                                        TakesValue::Necessary(_) => {
                                            return Err(ParseError::NeedsValue { flag, values });
                                        }
                                    }
                                }
                            }
                            TakesValue::Optional(values, default) => {
                                if index < bytes.len() - 1 {
                                    let remnants = bytes_to_os_str(&bytes[index + 1..]);
